def months_between(a, b):
    ya, ma = map(int, a[:7].split('-')); yb, mb = map(int, b[:7].split('-'))
    return (yb - ya) * 12 + (mb - ma)


def fa_opening():
    out = []
    for name, acq, cost, life, salvage in FA:
        start = acq[:7]
        used = months_between(start, CUTOFF) + 1 if life else 0  # cut-off сар хүртэл (дуустал)
        accum = 0 if not life else min(cost - salvage, round((cost - salvage) / life * min(used, life), 2))
        out.append(dict(name=name, acq=acq, cost=cost, life=life, salvage=salvage, start=start, used=used, accum=accum,
                        intangible=('биет бус' in name), land=(life == 0), rou=('ROU' in name)))
    return out


